from taf.sbts.oam.coam.admin import admin

from taf.ul.kpi_selector.utilities.kpi_logger import log_env_state

CELL_ID_PARAM_NAMES = {"lte": "globalCellId", "nr": "globalCellId", "wcdma": "cellId", "gsm": None}
CELL_CLASS_NAMES = {"lte": "LNCEL", "nr": "NRCELL", "wcdma": "WNCEL", "gsm": "GNCEL"}


class Cell(object):
    """
    Representation of Cell parameters. Gets all necessary parameters from Cell and test line configuration file
    to set proper timeout for operations.
    """

    def __init__(self, type, id):
        self.type = type
        self.id = id
        self.id_param = CELL_ID_PARAM_NAMES[type]
        self.parent_rmods = None
        self.class_name = CELL_CLASS_NAMES[type]
        self._is_super_cell = None
        self._admin = admin()
        self._connection = 'admin_connection_kpi_selector'
        self._technology = None
        self._runtime_distname = None
        self._is_beamforming_vector_transfer_active = None

    def __str__(self):
        return "Cell of type: {} and id: {}".format(self.type, self.id)

    @property
    def technology(self):
        """
        Cell technology i.e. "FDD", "TDD"
        """
        if self._technology is None:
            self._technology = self._get_cell_technology()

        log_env_state("Detected cell technology: {}".format(self._technology))

        return self._technology

    @property
    def is_super_cell(self):
        """
        True if cell is a Super Cell, False otherwise
        """
        if self._is_super_cell is None:
            if self.type != "nr":
                self._is_super_cell = False
            else:
                self._is_super_cell = self._is_nr_cell_supercell()

        return self._is_super_cell

    @property
    def runtime_distname(self):
        """
        Runtime distname of cell
        """
        if self._runtime_distname is None:
            self._runtime_distname = self._get_runtime_distname()

        return self._runtime_distname

    @property
    def is_beamforming_vector_transfer_active(self):
        """
        Checks if dynamic/custom beamforming weight vector file transfer is active
        (actDlSrsBm, actUlSrsBm set to True and dlMimoMode='8x4 Closed Loop Spatial Multiplexing'
        or NRCELL.basicBeamSet.customBeamSetName configured)
        """
        if self._is_beamforming_vector_transfer_active is None:
            if not self.type == "nr":
                self._is_beamforming_vector_transfer_active = False
            else:
                self._is_beamforming_vector_transfer_active = self._check_if_beamforming_vector_transfer_active()

        return self._is_beamforming_vector_transfer_active

    def _is_nr_cell_supercell(self):
        runtime_distname = self.runtime_distname
        for managed_object in \
                self._admin.get_managed_objects(connection=self._connection, class_name="NRCELL_R"):
            if managed_object["distName"] == runtime_distname:
                try:
                    return bool(managed_object["parameters"]["numOfSuperSubCells"])
                except KeyError:
                    return False

    def _get_runtime_distname(self):
        cell_info = self._admin.get_cells_info(connection=self._connection, cell_type=self.type)
        for cell in cell_info:
            if cell["id"]["configuration"].split("-")[-1] == str(self.id):
                return cell["id"]["internal"]

    def _get_cell_technology(self):
        if self.type in ["gsm", "wcdma"]:
            return "FDD"

        cells_info = self._admin.get_cells_info(connection=self._connection, cell_type=self.type)
        for cell in cells_info:
            if cell[self.id_param] == self.id:
                return cell["technology"]

    def _check_if_beamforming_vector_transfer_active(self):
        info = self._admin.get_managed_objects(connection=self._connection, class_name="NRCELL_A")
        for cell_info in info:
            if cell_info['distName'].split('-')[-1] == str(self.id):
                custom_beam_set = cell_info['parameters']['beamSet']['customBeamSetName']
                act_dl_bm = cell_info['parameters']['actDlSrsBm']
                act_ul_bm = cell_info['parameters']['actUlSrsBm']
                mimo_mode = str(cell_info['parameters']['dlMimoMode'])
                if custom_beam_set or (act_dl_bm and act_ul_bm and mimo_mode == '8x4 Closed Loop Spatial Multiplexing'):
                    return True
        return False
